<script>
  const timeline = document.getElementById('timeline');
  const earlyImage = document.querySelector('.visual-sticky .early');
  const laterImage = document.querySelector('.visual-sticky .later');
  const janSection = document.getElementById('jan-2027');
  const monthLinks = [...timeline.querySelectorAll('a')];

  function updatePageState() {
    const y = window.scrollY;
    timeline.classList.toggle('visible', y > 620);
    const lateEra = y > janSection.offsetTop - 500;
    earlyImage.style.display = lateEra ? 'none' : 'block';
    laterImage.style.display = lateEra ? 'block' : 'none';

    let current = 'mid-2025';
    for (const sectionId of ['mid-2025','late-2025','2026','mid-2026','late-2026','jan-2027','feb-2027','mar-2027','april-2027','may-2027','june-2027','july-2027','aug-2027','sep-2027','oct-2027']) {
      const section = document.getElementById(sectionId);
      if (section && section.getBoundingClientRect().top < 230) current = sectionId;
    }
    monthLinks.forEach(link => link.classList.toggle('active', link.getAttribute('href') === '#' + current));
  }
  window.addEventListener('scroll', updatePageState, { passive: true });
  window.addEventListener('resize', updatePageState);
  updatePageState();
</script>
